const stamp = name => [
  `<a:CreationDate>1700000000</a:CreationDate>`,
  `<a:Creator>${name}</a:Creator>`,
  `<a:ModificationDate>1700000000</a:ModificationDate>`,
  `<a:Modifier>${name}</a:Modifier>`,
];

const column = (id, guid, name, code, extra) => [
  `<o:Column Id="${id}">`,
  `<a:ObjectID>${guid}</a:ObjectID>`,
  `<a:Name>${name}</a:Name>`,
  `<a:Code>${code}</a:Code>`,
  ...stamp('tester'),
  ...extra,
  '</o:Column>',
];

const symbol = (id, table, rect) => [
  `<o:TableSymbol Id="${id}">`,
  `<a:Rect>${rect}</a:Rect>`,
  '<a:LineColor>16512</a:LineColor>',
  '<c:Object>',
  `<o:Table Ref="${table}"/>`,
  '</c:Object>',
  '</o:TableSymbol>',
];

