export const danglingRefs = (xml) => {
  const defined = new Set((xml.match(/ Id="o\d+"/g) || []).map(m => m.slice(5, -1)));
  return (xml.match(/ Ref="o\d+"/g) || []).map(m => m.slice(6, -1)).filter(r => !defined.has(r));
};
